import{GARDEN_CONFIG as f}from"./config.min.js";export function dollyTrackZ(o,t=f){const l=t.camera.dolly;return{near:Math.min(l.near.z,o),far:Math.max(l.far.z,o)}}export function dollyView(o,t,l=f){const r=l.camera.dolly,k=Math.max(-1,Math.min(1,o||0)),y=dollyTrackZ(t.z,l),a=k>=0?{z:y.near,y:r.near.y,lookY:r.near.lookY,lookZ:r.near.lookZ}:{z:y.far,y:r.far.y,lookY:r.far.lookY,lookZ:r.far.lookZ},u=Math.abs(k),e=(i,c)=>i+(c-i)*u;return{z:e(t.z,a.z),y:e(t.y,a.y),lookY:e(t.lookY,a.lookY),lookZ:e(t.lookZ,a.lookZ)}}let n=0;export function applyDollyDelta(o){o===o&&(n=Math.max(-1,Math.min(1,n+o)))}export function dollyLimits(){return{atIn:n>=1-1e-4,atOut:n<=-1+1e-4}}export function getDolly(){return n}export function resetView(){n=0}
